const EMPTY_CART = { items: [], coupon: null, subtotal: 0, discount: 0, total: 0 };
const COUPONS = { SAVE10: 10, HALF: 50 };
const MAX_QTY = 10;

// Every change goes through here, so the totals can never go stale.
function withTotals(items, coupon) {
  const subtotal = items.reduce((sum, line) => sum + line.price * line.qty, 0);
  const discount = coupon ? Math.floor((subtotal * coupon.percent) / 100) : 0;
  return { items, coupon, subtotal, discount, total: subtotal - discount };
}

function cartReducer(state, action) {
  const { items, coupon } = state;
  const hasLine = (id) => items.some((line) => line.id === id);

  switch (action.type) {
    case 'add': {
      const { id, name, price } = action.item;
      const existing = items.find((line) => line.id === id);
      if (!existing) return withTotals([...items, { id, name, price, qty: 1 }], coupon);
      if (existing.qty >= MAX_QTY) return state;
      return withTotals(
        items.map((line) => (line.id === id ? { ...line, qty: line.qty + 1 } : line)),
        coupon
      );
    }
    case 'setQty': {
      if (!hasLine(action.id)) return state;
      if (action.qty <= 0) return withTotals(items.filter((line) => line.id !== action.id), coupon);
      const qty = Math.min(action.qty, MAX_QTY);
      return withTotals(items.map((line) => (line.id === action.id ? { ...line, qty } : line)), coupon);
    }
    case 'remove': {
      if (!hasLine(action.id)) return state;
      return withTotals(items.filter((line) => line.id !== action.id), coupon);
    }
    case 'applyCoupon': {
      const code = String(action.code).trim().toUpperCase();
      if (!Object.prototype.hasOwnProperty.call(COUPONS, code)) return state;
      return withTotals(items, { code, percent: COUPONS[code] });
    }
    case 'removeCoupon':
      return withTotals(items, null);
    case 'clear':
      return EMPTY_CART;
    default:
      return state;
  }
}

function replayCart(actions) {
  const history = [];
  let state = EMPTY_CART;
  for (const action of actions) {
    state = cartReducer(state, action);
    history.push(state);
  }
  return history;
}

