reference.javascript:
const MIN_QUERY_LENGTH = 2;

function firedSearches(keystrokes, delayMs) {
  const sent = [];
  let lastSent = null;

  for (let i = 0; i < keystrokes.length; i++) {
    const { t, value } = keystrokes[i];
    const fireAt = t + delayMs;
    const next = keystrokes[i + 1];
    // The next keystroke cancels this timer only if it arrives before it fires.
    if (next && next.t < fireAt) continue;

    const query = value.trim();
    if (query.length < MIN_QUERY_LENGTH || query === lastSent) continue;
    sent.push({ at: fireAt, query });
    lastSent = query;
  }
  return sent;
}

