function firedSearches(keystrokes, delayMs) {
  const sent = [];
  let lastSent = null;
  let timerAt = null;
  let latest = '';

  const fire = () => {
    const query = latest.trim();
    if (query.length >= MIN_QUERY_LENGTH && query !== lastSent) {
      sent.push({ at: timerAt, query });
      lastSent = query;
    }
    timerAt = null;
  };

  for (const { t, value } of keystrokes) {
    if (timerAt !== null && t >= timerAt) fire();
    latest = value;
    if (timerAt === null) timerAt = t + delayMs; // timer starts on the first key of a burst
  }
  if (timerAt !== null) fire();
  return sent;
}

