function relativeTime(nowMs, thenMs) {
  // your code: return "just now", "5 minutes ago", "yesterday", "Mar 5", ...
}

reference.javascript:
const MINUTE = 60 * 1000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function ago(count, unit) {
  return count + ' ' + unit + (count === 1 ? '' : 's') + ' ago';
}

function relativeTime(nowMs, thenMs) {
  const diff = nowMs - thenMs;
  if (diff < MINUTE) return 'just now'; // also covers a slightly future thenMs
  if (diff < HOUR) return ago(Math.floor(diff / MINUTE), 'minute');
  if (diff < DAY) return ago(Math.floor(diff / HOUR), 'hour');

  // Calendar days in UTC: epoch milliseconds start at UTC midnight.
  const days = Math.floor(nowMs / DAY) - Math.floor(thenMs / DAY);
  if (days === 1) return 'yesterday';
  if (days < 7) return days + ' days ago';

  const then = new Date(thenMs);
  const label = MONTHS[then.getUTCMonth()] + ' ' + then.getUTCDate();
  const sameYear = then.getUTCFullYear() === new Date(nowMs).getUTCFullYear();
  return sameYear ? label : label + ', ' + then.getUTCFullYear();
}

