reference.javascript:
const AGE_MESSAGE = 'Age must be a whole number from 13 to 120';

function asText(value) {
  return value === null || value === undefined ? '' : String(value);
}

function usernameError(value) {
  const username = asText(value).trim();
  if (username === '') return 'Username is required';
  if (username.length < 3 || username.length > 20) return 'Username must be 3 to 20 characters';
  if (!/^[A-Za-z0-9_]+$/.test(username)) return 'Username can only contain letters, numbers and _';
  return null;
}

function isValidEmail(email) {
  if (email.includes(' ')) return false;
  const parts = email.split('@');
  if (parts.length !== 2 || parts[0] === '') return false;
  const domainParts = parts[1].split('.');
  return domainParts.length >= 2 && domainParts.every((part) => part !== '');
}

function emailError(value) {
  const email = asText(value).trim();
  if (email === '') return 'Email is required';
  if (!isValidEmail(email)) return 'Enter a valid email address';
  return null;
}

function passwordError(value) {
  const password = asText(value);
  if (password === '') return 'Password is required';
  if (password.length < 8) return 'Password must be at least 8 characters';
  if (!/[A-Za-z]/.test(password) || !/[0-9]/.test(password)) return 'Password must contain a letter and a number';
  return null;
}

function ageError(value) {
  if (value === null || value === undefined) return null;
  let age = value;
  if (typeof value !== 'number') {
    const text = String(value).trim();
    if (text === '') return null; // not given
    if (!/^[0-9]+$/.test(text)) return AGE_MESSAGE;
    age = Number(text);
  }
  if (!Number.isInteger(age) || age < 13 || age > 120) return AGE_MESSAGE;
  return null;
}

function validateSignup(form) {
  const errors = {};
  const report = (field, message) => {
    if (message) errors[field] = message;
  };
  report('username', usernameError(form.username));
  report('email', emailError(form.email));
  const passwordProblem = passwordError(form.password);
  report('password', passwordProblem);
  if (!passwordProblem && form.confirmPassword !== form.password) {
    report('confirmPassword', 'Passwords do not match');
  }
  report('age', ageError(form.age));
  if (form.acceptTerms !== true) report('acceptTerms', 'You must accept the terms');
  return errors;
}

