  switch (command.op) {
    case 'type': {
      const before = snapshot();
      text = text.slice(0, cursor) + command.text + text.slice(cursor);
      cursor += command.text.length;
      recordEdit(command, before);
      break;
    }
    case 'backspace': {
      if (cursor > 0) {
        const before = snapshot();
        text = text.slice(0, cursor - 1) + text.slice(cursor);
        cursor -= 1;
        recordEdit(command, before);
      }
      break;
    }
    case 'move':
      cursor = Math.min(Math.max(command.to, 0), text.length);
      break;
    case 'undo': {
      const step = undoStack.pop();
      if (step) {
        redoStack.push(step);
        restore(step.before);
      }
      break;
    }
    case 'redo': {
      const step = redoStack.pop();
      if (step) {
        undoStack.push(step);
        text = step.after.text;
        cursor = text.length;
      }
      break;
    }
  }
  previous = command;
  return { text, cursor, canUndo: undoStack.length > 0, canRedo: redoStack.length > 0 };
